local function a(b)return string.match(b,'^()[%s%z]*$')and''or string.match(b,'^[%s%z]*(.*[^%s%z])')end;local c={}function c.parseControl(d)local e={}local f=nil;for g in string.gmatch(d,"[^\n]+")do if string.sub(g,1,1)==" "and f~=nil then if f=="Description"then if type(e[f])=="string"then e[f]={Short=e[f],Long=""}end;e[f].Long=e[f].Long..(string.sub(g,2)=="."and"\n\n"or string.sub(g,2))else e[f]=e[f].."\n"..(string.sub(g,2)=="."and"\n"or string.sub(g,2))end else f=string.sub(g,1,(string.find(g,":")or 0)-1)e[f]=a(string.sub(g,(string.find(g,":")or-1)+1))end end;return e end;function c.parseControlList(d,h)local e={}local i={}local j={}local b=1;for k,g in string.gmatch(d,"()([^\n]*\n)")do if g=="\n"or g==""then b=b+1 else j[b]=j[b]or k;i[b]=(i[b]or"")..g end end;for l,m in pairs(i)do local n=c.parseControl(m)if h then n.__pos=j[l]end;table.insert(e,n)end;return e end;function c.parseDependencies(o)local e={}for p in string.gmatch(o,"[^,]+")do p=a(p)local q={}if string.find(p,"|")then q.multiple=true;q.names={}for r in string.gmatch(p,"[^|]+")do r=a(r)local s={}s.name=string.match(r,"%S+")if string.match(r,"%([<>=]+ [%w.%-%+%~]+%)")then s.rel=string.match(r,"%(([<>=]+) [%w.%-%+%~]+%)")s.version=string.match(r,"%([<>=]+ ([%w.%-%+%~]+)%)")end;table.insert(q.names,s)end else q.name=string.match(p,"%S+")if string.match(p,"%([<>=]+ [%w%.%-%+%~]+%)")then q.rel=string.match(p,"%(([<>=]+) [%w.%-%+%~]+%)")q.version=string.match(p,"%([<>=]+ ([%w.%-%+%~]+)%)")end end;table.insert(e,q)end;return e end;return c
